"use server";

import { revalidatePath } from "next/cache";

// Simulated database for notification preferences
const notificationPreferences: Record<string, boolean> = {
  "user-1": false,
};

export async function getNotificationPreference(
  userId: string
): Promise<boolean> {
  return notificationPreferences[userId] ?? false;
}

export async function toggleNotification(userId: string): Promise<void> {
  const current = notificationPreferences[userId] ?? false;
  notificationPreferences[userId] = !current;

  revalidatePath("/");
}

