import { getNotificationPreference, toggleNotification } from "./actions";

const USER_ID = "user-1";

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference(USER_ID);

  return (
    <main>
      <h1>Settings</h1>
      <section>
        <h2>Notifications</h2>
        <p>
          Notifications are currently{" "}
          <strong>{notificationsEnabled ? "ON" : "OFF"}</strong>
        </p>
        <form action={toggleNotification.bind(null, USER_ID)}>
          <button type="submit">
            Turn {notificationsEnabled ? "OFF" : "ON"}
          </button>
        </form>
      </section>
    </main>
  );
}

